  const seen = world(on, {
    files: {
      "package.json": MANIFEST,
      "bun.lock": '{ "packages": { "left-padx": ["left-padx@1.0.0"] } }',
    },
    registry: { "left-padx": 404 },
  });
  expect((await bash($, "bun add left-padx@1")).decision).toBe("allow");
