const complete = ($: Engine, model: string, extra: object = {}) =>
  $.turn.complete({
    answer: "Done.",
    durationMs: 10,
    isAborted: false,
    turnId: "t1",
    reason: "answer",
    usage: {
      input_tokens: 1,
      output_tokens: 1,
      cache_read_input_tokens: 0,
      cache_creation_input_tokens: 0,
      model,
    },
    ...extra,
  });

